#include <bits/stdc++.h>
using namespace std;

constexpr int MAX_N = 24;
constexpr size_t MAX_MASK = size_t{1} << MAX_N;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    int A[MAX_N];
    for (int i = 0; i < N; ++i) cin >> A[i];
    sort(A, A + N, greater<int>());

    static bitset<MAX_MASK> t, f;
    vector<uint32_t> T;

    for (int i = 0; i < N; ++i) {
        uint32_t mask = uint32_t{1} << i;
        if (A[i] == 1) {
            t.set(mask);
            T.push_back(mask);
        }
    }

    const uint32_t limit = uint32_t{1} << N;

    for (uint32_t mask = 0; mask < limit; ++mask) {
        uint32_t low = mask & -mask;

        if (low != 0 && A[__builtin_ctz(low)] == 1) {
            f.set(mask);
            continue;
        }

        for (size_t i = 0; i < T.size() && !f[mask]; ++i) {
            uint32_t part = T[i];
            if ((mask & part) == part) {
                uint32_t rest = mask ^ part;
                if (t[rest] || f[rest]) f.set(mask);
            }
        }

        if (low != 0 &&
            __builtin_popcount(mask) == A[__builtin_ctz(low)] &&
            f[mask ^ low]) {
            t.set(mask);
        }

        if (t[mask]) T.push_back(mask);
    }

    cout << (t[limit - 1] ? "YES\n" : "NO\n");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

struct Mask24 {
    unsigned char b0, b1, b2;

    Mask24(uint32_t x)
        : b0(x & 255), b1((x >> 8) & 255), b2((x >> 16) & 255) {}

    uint32_t value() const {
        return uint32_t(b0) | (uint32_t(b1) << 8) | (uint32_t(b2) << 16);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> A(N);
    for (int &x : A) cin >> x;
    sort(A.begin(), A.end(), greater<int>());

    const uint32_t total = 1u << N;
    vector<uint64_t> t((total + 63) / 64, 0);
    vector<uint64_t> f((total + 63) / 64, 0);

    auto getBit = [](const vector<uint64_t>& bits, uint32_t x) {
        return (bits[x >> 6] >> (x & 63)) & 1ULL;
    };
    auto setBit = [](vector<uint64_t>& bits, uint32_t x) {
        bits[x >> 6] |= 1ULL << (x & 63);
    };

    vector<Mask24> trueMasks;
    trueMasks.reserve(total);

    for (int i = 0; i < N; ++i) {
        if (A[i] == 1) {
            uint32_t mask = 1u << i;
            setBit(t, mask);
            trueMasks.emplace_back(mask);
        }
    }

    for (uint32_t mask = 0; mask < total; ++mask) {
        if (mask != 0) {
            uint32_t low = mask & -mask;
            int index = __builtin_ctz(low);

            if (A[index] == 1) {
                setBit(f, mask);
                continue;
            }

            for (const Mask24& stored : trueMasks) {
                if (getBit(f, mask)) break;

                uint32_t part = stored.value();
                if ((mask & part) == part) {
                    uint32_t rest = mask ^ part;
                    if (getBit(t, rest) || getBit(f, rest))
                        setBit(f, mask);
                }
            }

            if (__builtin_popcount(mask) == A[index] &&
                getBit(f, mask ^ low)) {
                setBit(t, mask);
            }

            if (getBit(t, mask))
                trueMasks.emplace_back(mask);
        }
    }

    cout << (getBit(t, total - 1) ? "YES\n" : "NO\n");
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

constexpr int MAX_N = 24;
constexpr int MAX_MASK = 1 << MAX_N;

int N;
int A[MAX_N];
bitset<MAX_MASK> t, f;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;
    for (int i = 0; i < N; ++i) cin >> A[i];
    sort(A, A + N, greater<int>());

    const int limit = 1 << N;
    auto masks = make_unique<unsigned char[]>(3ULL * limit);
    int count = 0;

    auto addMask = [&](int mask) {
        size_t p = 3ULL * count++;
        masks[p] = static_cast<unsigned char>(mask);
        masks[p + 1] = static_cast<unsigned char>(mask >> 8);
        masks[p + 2] = static_cast<unsigned char>(mask >> 16);
    };

    auto getMask = [&](int index) {
        size_t p = 3ULL * index;
        return int(masks[p]) |
               (int(masks[p + 1]) << 8) |
               (int(masks[p + 2]) << 16);
    };

    for (int i = 0; i < N; ++i) {
        int mask = 1 << i;
        if (A[i] == 1) {
            t[mask] = true;
            addMask(mask);
        }
    }

    for (int mask = 0; mask < limit; ++mask) {
        int low = mask & -mask;
        int value = low ? A[__builtin_ctz(static_cast<unsigned>(low))] : 0;

        if (low && value == 1) {
            f[mask] = true;
            continue;
        }

        for (int i = 0; i < count && !f[mask]; ++i) {
            int part = getMask(i);
            if ((mask & part) == part && (t[mask ^ part] || f[mask ^ part]))
                f[mask] = true;
        }

        if (__builtin_popcount(static_cast<unsigned>(mask)) == value)
            t[mask] = t[mask] || f[mask ^ low];

        if (t[mask])
            addMask(mask);
    }

    cout << (t[limit - 1] ? "YES\n" : "NO\n");
}

