#include <bits/stdc++.h>
using namespace std;

class BitArray {
    vector<uint64_t> data;

public:
    explicit BitArray(size_t size) : data((size + 63) / 64, 0) {}

    bool get(uint32_t index) const {
        return (data[index >> 6] >> (index & 63)) & 1ULL;
    }

    void set(uint32_t index) {
        data[index >> 6] |= 1ULL << (index & 63);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> A(N);
    for (int& x : A) cin >> x;
    sort(A.begin(), A.end(), greater<int>());

    const uint32_t limit = 1U << N;
    BitArray t(limit), f(limit);
    vector<uint32_t> trueMasks;

    for (int i = 0; i < N; ++i) {
        if (A[i] == 1) {
            uint32_t mask = 1U << i;
            t.set(mask);
            trueMasks.push_back(mask);
        }
    }

    for (uint32_t mask = 1; mask < limit; ++mask) {
        uint32_t low = mask & (~mask + 1U);
        int lowIndex = __builtin_ctz(low);

        if (A[lowIndex] == 1) {
            f.set(mask);
            continue;
        }

        bool found = false;
        for (uint32_t sub : trueMasks) {
            if ((mask & sub) == sub) {
                uint32_t rest = mask ^ sub;
                if (t.get(rest) || f.get(rest)) {
                    found = true;
                    break;
                }
            }
        }

        if (found) f.set(mask);

        if (__builtin_popcount(mask) == A[lowIndex] && f.get(mask ^ low)) {
            t.set(mask);
            trueMasks.push_back(mask);
        }
    }

    cout << (t.get(limit - 1) ? "YES\n" : "NO\n");
    return 0;
}

